#!/usr/bin/env python3
import os
import magic

def analyze_file(filepath):
    file_info = {}
    file_info['size'] = os.path.getsize(filepath)
    file_info['type'] = magic.from_file(filepath)
    file_info['mime'] = magic.from_file(filepath, mime=True)
    return file_info

def analyze_directory(dir_path):
    print(f"\nAnalyzing directory: {dir_path}")
    for root, dirs, files in os.walk(dir_path):
        for fname in files:
            filepath = os.path.join(root, fname)
            if os.path.isfile(filepath):
                info = analyze_file(filepath)
                print(f"\nFile: {filepath}")
                print(f"Size: {info['size']} bytes")
                print(f"Type: {info['type']}")
                print(f"MIME: {info['mime']}")

if __name__ == '__main__':
    analyze_directory('.')

